const schema=JSON.stringify({type:'object',properties:{item:{type:'integer'},title:{type:'string'},status:{type:'string'},evidence:{type:'array',items:{type:'string'}},existing_test_coverage:{type:'array',items:{type:'string'}},minimal_regression_test:{type:'string'},safe_fix_outline:{type:'string'},preexisting_change_overlap:{type:'string'}},required:['item','title','status','evidence','existing_test_coverage','minimal_regression_test','safe_fix_outline','preexisting_change_overlap']});
const items=[
{n:1,title:'Resume eligibility: require a matching fingerprint and reject completed checkpoints',scope:'Inspect mmnext/infrastructure/repository/job_repository.py can_resume_job and mmnext/domain/models.py JobCheckpoint.can_resume; inspect tests/test_job_repository.py. Verify whether empty fingerprints and completed_units >= total_units can currently be accepted.'},
{n:2,title:'Malformed checkpoint schema: convert parse errors into safe refusal',scope:'Inspect mmnext/infrastructure/repository/job_repository.py load_checkpoint/can_resume_job and tests/test_job_repository.py. Determine whether nonnumeric/null schema_version raises beyond a structured rejection.'},
{n:3,title:'Job ID path safety: reject traversal and absolute components',scope:'Inspect all JobRepository path construction/read/write methods in mmnext/infrastructure/repository/job_repository.py and tests/test_job_repository.py. Check traversal, absolute and Windows drive/UNC path behavior on current code.'},
{n:4,title:'Transcript reopen: invalidate results after source/session changes',scope:'Inspect mmnext/ui/app_context.py set_source/reset/load, reopen token/result application, and tests/test_transcript_reopen_thread.py, tests/test_transcript_open.py. Verify generation/source/session identity is rechecked at apply time.'},
{n:5,title:'Transcript artifact duration: reject invalid and non-finite values',scope:'Inspect mmnext/application/job_service.py prepare_transcript_from_job and related tests/test_transcript_open.py. Check missing, zero, negative, NaN/infinity duration and row-end bounds.'},
{n:6,title:'Exact Dubbing concurrent renders: isolate intermediate work directories',scope:'Inspect mmnext/application/exact_dubbing_service.py create_coordinator, mmnext/infrastructure/exact_dubbing_render.py intermediate paths/cleanup, and tests/test_exact_dubbing_render.py. Verify whether concurrent service instances collide.'},
{n:7,title:'Exact Dubbing source duration gate: enforce one tolerance before rendering',scope:'Inspect mmnext/domain/validation.py validate_source_duration, mmnext/ui/app_context.py start_exact_dubbing_render, mmnext/infrastructure/exact_dubbing_render.py duration checks, and tests/test_exact_dubbing_validation_gate.py. Confirm current thresholds and call path.'},
{n:8,title:'Narrator fallback timeline coverage: handle gaps between transcript rows',scope:'Inspect mmnext/services/adapters/narrator.py fallback plan and tests/test_narrator_planning_service.py. Verify coverage of leading, inter-row and trailing intervals under current documented semantics.'},
{n:9,title:'Narrator translation checkpoints: scope persistence to a job/run',scope:'Inspect mmnext/ui/app_context.py narrator checkpoint path and mmnext/application/narrator_pipeline_coordinator.py checkpoint serialization; inspect tests/test_narrator_pipeline.py. Determine collision/isolation behavior.'},
{n:10,title:'Common Editing publication: render partial, validate, and atomically publish',scope:'Inspect mmnext/services/adapters/common_editing.py and mmnext/ui/common_editing_export_worker.py plus tests for Common Editing. Verify final path writes, validation, cleanup, cancellation and whether this real exporter is reachable.'},
{n:11,title:'Splitter directory render: propagate any per-part failure',scope:'Inspect mmnext/infrastructure/splitter_render.py render and tests/test_splitter_render.py. Determine callers and whether failed render_part results can yield True.'},
{n:12,title:'Splitter reuse: include source revision/content in cache identity',scope:'Inspect mmnext/application/splitter_render_coordinator.py fingerprint/reuse and tests/test_splitter_render.py. Check same-path source replacement behavior and existing identity metadata.'},
{n:13,title:'Common Editing thread ownership: prevent splitter completion clearing its reference',scope:'Inspect mmnext/ui/app_context.py splitter/common editing start/finished slots and tests/test_splitter_worker.py or other UI tests. Determine current identity checks and duplicate-run consequences.'},
{n:14,title:'Settings controls: persist values used by render operations',scope:'Inspect mmnext/ui/screens/settings_screen.py, mmnext/ui/app_context.py render settings consumers, and current UI tests. Determine which settings are disconnected and whether user-visible controls claim they are active.'},
{n:15,title:'Jobs Resume: align enabled state with valid transition target',scope:'Inspect mmnext/ui/screens/jobs_screen.py, mmnext/application/job_manager.py and tests/test_job_state_machine.py or UI tests. Verify FAILED/paused/stopped button/action transition matrix.'}
];
const results=await parallel('Recheck each approved medium-priority fix',()=>items.map(it=>agent(
'You are performing a READ-ONLY verification before a parent agent implements an approved repository fix. Repository root is J:\\mmnext-movie-recap-pro. Check exactly item '+it.n+': '+it.title+'. Scope: '+it.scope+'\nInspect current source and tests, not prior audit prose. Do not edit files or run the full test suite. Status must be exactly one of: confirmed, already_fixed, not_confirmed, blocked. Cite exact current file paths and line numbers. Distinguish real production paths from unused helpers. Identify tests that already cover behavior and the smallest missing regression test. Preserve project contracts: no real-to-demo fallback, no data loss, no GUI blocking, Exact Dubbing immutable id/original/start/duration, job-scoped atomic persistence. Explicitly note if the target file is already modified/untracked or the proposed change could collide with existing workspace edits. Return only JSON matching the schema.',
{brief:'Recheck item '+it.n+': '+it.title,schema,sandbox:'shared',effort_level:'standard'}
)),{schema});
return {results:results.map((r,i)=>r.ok?r.value:{item:items[i].n,title:items[i].title,status:'blocked',evidence:[],existing_test_coverage:[],minimal_regression_test:'',safe_fix_outline:'',preexisting_change_overlap:r.error.message})};

